  "status": "SUPPORTED",
  "claim": {
    "component_id": "C017",
    "value": "A single matching peak is insufficient grounds for accepting a candidate placement.",
    "scope": "Acceptance of proposed chronological alignments.",
    "provenance": {
      "refs": [
        {
          "source_id": "P011",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The mapping explicitly requires independent dates and additional histories instead of acceptance based on one matching peak."
    }
  },
  "signal_basis": {
    "component_id": "C017_signal_basis",
    "value": "Candidate placements are checked against independent dates and additional histories. The positive signal is repeated distinctive multi-day correspondence consistent with independent anchors and histories withheld from alignment selection; short or repetitive patterns can produce false alignments.",
    "scope": "Prospective assessment of chronological placements, assuming the described procedure is executed and its signal observed.",
    "provenance": {
      "refs": [
        {
          "source_id": "P011",
          "role": "SUPPORT"
        },
        {
          "source_id": "P015",
          "role": "SUPPORT"
        },
        {
          "source_id": "P027",
          "role": "SUPPORT"
        },
        {
          "source_id": "P018",
          "role": "CONTEXT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans supply the corroboration procedure, positive signal, false-alignment limitation and prospective scope."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C017_stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "No unresolved empirical relation is needed for this supported judgment."
    }
  },
  "rationale": "A lone matching peak cannot establish the repeated correspondence and independent corroboration required to accept a placement. Its compatibility with accidental or repetitive matches licenses the claim's narrow insufficiency judgment.",
  "uncertainty": "Corroborated alignments can still be mistaken; the claim does not assert that the fuller procedure guarantees correct placement.",
  "anomalies": []
}
